const c = $('Preparar Pasteles').first().json;
const r = $input.first().json;
if (!r.data?.length) throw new Error('Sin embeddings recibidos de OpenRouter');

const points = c.pasteles.map((x, i) => ({
  id: x.id,
  vector: r.data[i].embedding,
  payload: {
    nombre: x.nombre,
    descripcion: x.descripcion,
    perfil_sabor: x.perfil_sabor,
    textura: x.textura,
    porciones_min: x.porciones_min,
    porciones_max: x.porciones_max,
    precio_cop: x.precio_cop,
    alergenos: x.alergenos,
    vegano: x.vegano
  }
}));

return [{
  json: {
    ...c,
    vector_size: r.data[0].embedding.length,
    points
  }
}];

const b = $json.body ?? $json;
const mensaje = (b.mensaje ?? b.pregunta ?? '').trim();
if (!mensaje) throw new Error('Falta el mensaje o pregunta del usuario');

// Deteccion automatica de restricciones de seguridad alimentaria
const lower = mensaje.toLowerCase();
const alergenosExcluir = [];

if (lower.includes('gluten') || lower.includes('celiaco') || lower.includes('celíaco') || lower.includes('sin harina')) {
  alergenosExcluir.push('gluten');
}
if (lower.includes('lactosa') || lower.includes('lacteo') || lower.includes('lácteo') || lower.includes('sin leche')) {
  alergenosExcluir.push('lactosa');
}
if (lower.includes('huevo') || lower.includes('sin huevo')) {
  alergenosExcluir.push('huevo');
}
if (lower.includes('nuez') || lower.includes('nueces') || lower.includes('frutos secos') || lower.includes('almendra') || lower.includes('pistacho')) {
  alergenosExcluir.push('frutos_secos');
}

// Construccion del filtro determinista para Qdrant (must_not)
let filter = null;
if (alergenosExcluir.length > 0) {
  filter = {
    must_not: alergenosExcluir.map(al => ({
      key: 'alergenos',
      match: { value: al }
    }))
  };
}

return [{
  json: {
    pregunta: mensaje,
    sessionId: b.sessionId ?? 'default_session',
    alergenos_excluidos: alergenosExcluir,
    filter,
    qdrant_url: 'http://panaderia-qdrant:6333',
    coleccion: 'pasteleria',
    modelo_embedding: 'openai/text-embedding-3-small',
    limite: 4
  }
}];

const c = $('Prepara Pregunta & Filtros').first().json;
const r = $input.first().json;
if (!r.data?.length) throw new Error('No se pudo generar embedding para la consulta');
return [{
  json: {
    ...c,
    vector: r.data[0].embedding
  }
}];

