const config = $('Prepara Pregunta & Filtros').first().json;
const respuesta = $input.first().json;
const puntos = respuesta.result?.points ?? respuesta.result ?? [];

if (!Array.isArray(puntos) || puntos.length === 0) {
  return [{
    json: {
      pregunta: config.pregunta,
      alergenos_excluidos: config.alergenos_excluidos,
      mejor_resultado: null,
      pasteles: []
    }
  }];
}

const pasteles = puntos.map((p, idx) => ({
  posicion: idx + 1,
  id: p.id,
  nombre: p.payload?.nombre ?? 'Pastel artesanal',
  descripcion: p.payload?.descripcion ?? '',
  perfil_sabor: p.payload?.perfil_sabor ?? '',
  textura: p.payload?.textura ?? '',
  porciones_min: p.payload?.porciones_min ?? 8,
  porciones_max: p.payload?.porciones_max ?? 12,
  precio_cop: p.payload?.precio_cop ?? 80000,
  alergenos: p.payload?.alergenos ?? [],
  vegano: Boolean(p.payload?.vegano),
  score: Number(p.score ?? 0)
}));

return [{
  json: {
    pregunta: config.pregunta,
    alergenos_excluidos: config.alergenos_excluidos,
    mejor_resultado: pasteles[0] ?? null,
    pasteles
  }
}];

const { pregunta, pasteles, alergenos_excluidos } = $json;

if (!pasteles || pasteles.length === 0) {
  return [{
    json: {
      pregunta,
      pasteles: [],
      prompt: `El cliente preguntó: "${pregunta}", pero tras aplicar el filtro de seguridad de alérgenos (${alergenos_excluidos.join(', ') || 'ninguno'}) no se encontraron pasteles compatibles. Pide disculpas amablemente y ofrece consultar si el chef puede elaborar una receta personalizada.`
    }
  }];
}

const contexto = pasteles.map((p, idx) => {
  const al = p.alergenos.length > 0 ? p.alergenos.join(', ') : 'Ninguno (Libre de alérgenos principales)';
  return `Pastel #${idx + 1}: ${p.nombre}
- Descripción: ${p.descripcion}
- Perfil de sabor: ${p.perfil_sabor} | Textura: ${p.textura}
- Porciones: ${p.porciones_min} a ${p.porciones_max}
- Precio: $${p.precio_cop.toLocaleString('es-CO')} COP
- Alérgenos: [${al}]
- Vegano: ${p.vegano ? 'Sí' : 'No'}`;
}).join('\n\n');

const prompt = `Eres una asesora experta y amable de 'Pastelería Dulce Deleite'.
Tu misión es recomendar los pasteles recuperados garantizando la seguridad alimentaria del cliente.

REGLAS DE RESPUESTA:
1. Responde de forma cálida, persuasiva y artesanal.
2. Recomienda 1 o 2 de las mejores opciones del contexto según lo que pidió el usuario.
3. Destaca por qué encaja con su gusto y menciona que sus alérgenos han sido verificados y excluidos de forma segura.
4. Invita al cliente a hacer clic en 'Reservar' en la tarjeta para confirmar la fecha y apartar su cupo en cocina.

CONTEXTO DE PASTELES DISPONIBLES:
${contexto}

CONSULTA DEL CLIENTE:
${pregunta}`;

return [{
  json: {
    pregunta,
    contexto,
    prompt,
    pasteles
  }
}];

