const respuestaLLM = $input.first().json;
const datos = $('Preparar Contexto Asesora').first().json;

const texto = respuestaLLM.choices?.[0]?.message?.content;
if (!texto) throw new Error('OpenRouter no devolvió una respuesta válida.');

return [{
  json: {
    pregunta: datos.pregunta,
    texto,
    pasteles: datos.pasteles
  }
}];
